namespace ghidra.file.formats.android.bootldr;





using ghidra.app.util.bin;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

/* @FileSystemInfo(type = "androidbootloader", description = "Android Boot Loader Image", factory = typeof(GFileSystemBaseFactory)) */
public class AndroidBootLoaderFileSystem : GFileSystemBase {
	private List<GFileImpl> fileList = new();
	private List<Integer> offsetList = new();

	public AndroidBootLoaderFileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		byte[] bytes = provider.readBytes(0, AndroidBootLoaderConstants.BOOTLDR_MAGIC_SIZE);
		return AndroidBootLoaderConstants.BOOTLDR_MAGIC.equals(new string(bytes).trim());
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		BinaryReader reader = new BinaryReader(provider, true /*might not always be LE*/ );
		AndroidBootLoaderHeader header = new AndroidBootLoaderHeader(reader);
		int runningOffset = header.getStartOffset();
		foreach (AndroidBootLoaderImageInfo imageInfo in header.getImageInfoList()) {

			GFileImpl file = GFileImpl.fromFilename(this, root, imageInfo.getName(), false,
				imageInfo.getSize(), null);

			fileList.add(file);
			offsetList.add(runningOffset);

			runningOffset += imageInfo.getSize();
		}
	}

	/* @Override */
	public List<GFile> getListing(GFile directory)
    {
		return new(fileList);
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {
		int index = fileList.indexOf(file);
		if (index < 0) {
			throw new IOException("Unknown file: " + file);
		}
		int offset = offsetList.get(index);
		return new ByteProviderWrapper(provider, offset, file.getLength(), file.getFSRL());
	}

}
